tool_args.content:
{
  "analysis_1_factorial": {
    "design": {
      "description": "2x2 ANOVA: Count(8 vs 16) x BCS(low vs high), within 40-rel pool",
      "count_levels": [8, 16],
      "bcs_split": "within-count median",
      "bcs_median_count8": 0.7094,
      "bcs_median_count16": 0.7872,
      "n_per_cell": {"low_count_low_bcs": 14, "low_count_high_bcs": 13, "high_count_low_bcs": 14, "high_count_high_bcs": 13},
      "total_n": 54
    },
    "anova": {
      "count_F": 10.976, "count_p": 0.0017, "count_eta2": 0.175,
      "bcs_F": 1.236, "bcs_p": 0.2716, "bcs_eta2": 0.020,
      "interaction_F": 0.598, "interaction_p": 0.4431, "interaction_eta2": 0.010
    },
    "tost": {"interaction_effect_pp": -3.77, "ci_90": [-11.93, 4.40], "equivalence_margin_pp": 3.0, "p_tost": 0.5622, "conclusion": "inconclusive"}
  },
  "analysis_2_regression": {
    "design": {"description": "Regression: accuracy ~ log2(count) + BCS + interaction, count 4-40 from 40-rel", "count_levels": [4, 8, 16, 32, 40], "total_n": 69},
    "coefficients": {"log_count_z": -0.0354, "bcs_z": -0.0507, "interaction": 0.0047},
    "p_values": {"log_count": 0.0076, "bcs": 0.0002, "interaction": 0.6077},
    "tost": {"interaction_effect_pp": 0.47, "interaction_se_pp": 0.90, "p_tost": 0.0033, "conclusion": "equivalent"},
    "r_squared": 0.523
  },
  "analysis_3_cross_dataset": {
    "design": {"description": "2x2 ANOVA: Pool diversity x BCS, N=200", "total_n": 200},
    "anova": {"pool_F": 21.90, "pool_p": 0.000005, "bcs_F": 5.90, "bcs_p": 0.0161, "interaction_F": 2.76, "interaction_p": 0.0981},
    "tost": {"interaction_effect_pp": 3.05, "ci_90": [0.02, 6.08], "p_tost": 0.5109, "conclusion": "inconclusive"}
  },
  "overall_conclusion": {
    "no_significant_interaction_all_three": true,
    "tost_equivalent_regression": true,
    "summary": "Count and BCS channels are empirically separable: both significant predictors, no interaction in all three analyses, TOST confirmed in regression (p=0.003)."
  }
}
